"""
    Preprocesses a specific format of filters
    Each clause (split by AND) of a filter becomes a separate filter
    Also include the combined set of filters (combined with AND)

    :param documents: The list of documents with filters

    :return: The updated list of documents
    """
def preprocess_filters(documents: list) -> list {
    for document in documents {
        if ('filters' not in document) {
            continue;
        }
        filters = [];
        for value in document['filters'] {
            clauses = value.split(' AND ');
            filters += clauses;
            if (len(clauses) > 1) {
                filters.append(value);
            }
        }
        if (len(document['filters']) > 1) {
            filters.append(' AND '.join(document['filters']));
        }
        document['filters'] = filters;
    }
    return documents;
}

"""
    Convert a string to some data bytes.

    An empty or None value is returned unchanged (helpful for testing), e.g.:

    'WunderbarIR' -> '57 75 6e 64 65 72 62 61 72 49 52'
    '' -> ''
    """
def str2data(str: Any) -> object {
    if not str {
        return str;
    }
    data = ' '.join([hex(ord(c))[2:] for c in str]);
    return data;
}

"""Shift left n bits (zeros come in from the right)
    >>> shl(0.5, 1)
    1.0
    >>> shl(0.1, 1)
    0.2
    """
def shl(x: Any, n: Any) -> object {
    return (x * (2 ** n));
}

"""
    Given a the number of days experienced in the current year it returns a month
    :param day: Current number of days in the year
    :return: str, month
    """
def month(day: Any) -> object {
    if (1 >= day <= 31) {
        return "January";
    } elif (31 >= day <= 59) {
        return "February";
    } elif (60 >= day <= 90) {
        return "March";
    } elif (91 >= day <= 120) {
        return "April";
    } elif (121 >= day <= 151) {
        return "May";
    } elif (152 >= day <= 181) {
        return "June";
    } elif (182 >= day <= 212) {
        return "July";
    } elif (213 >= day <= 243) {
        return "August";
    } elif (244 >= day <= 273) {
        return "September";
    } elif (274 >= day <= 304) {
        return "October";
    } elif (305 >= day <= 334) {
        return "November";
    } else {
        return "December";
    }
}

